-- PostgreSQL 15+; synthetic engagement metadata only.
CREATE SCHEMA IF NOT EXISTS diplomacy_demo;
CREATE TABLE IF NOT EXISTS diplomacy_demo.missions(mission_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,mission_code TEXT NOT NULL UNIQUE,country_code CHAR(2) NOT NULL,post_type TEXT NOT NULL CHECK(post_type IN('embassy','high_commission','consulate','multilateral','headquarters')),is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS diplomacy_demo.engagements(engagement_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,engagement_ref TEXT NOT NULL UNIQUE,mission_id BIGINT NOT NULL REFERENCES diplomacy_demo.missions(mission_id) ON DELETE RESTRICT,engagement_type TEXT NOT NULL CHECK(engagement_type IN('bilateral_meeting','consular_outreach','trade_promotion','multilateral_session','other')),held_at TIMESTAMPTZ NOT NULL,topic_code TEXT NOT NULL,summary TEXT NOT NULL,publication_state TEXT NOT NULL DEFAULT 'internal_summary' CHECK(publication_state IN('draft','internal_summary','approved_public','withheld')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS diplomacy_demo.commitments(commitment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,commitment_ref TEXT NOT NULL UNIQUE,engagement_id BIGINT NOT NULL REFERENCES diplomacy_demo.engagements(engagement_id) ON DELETE RESTRICT,action_summary TEXT NOT NULL,owner_ref TEXT NOT NULL,due_date DATE,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','completed','cancelled')),completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS diplomacy_demo.commitment_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,commitment_id BIGINT NOT NULL REFERENCES diplomacy_demo.commitments(commitment_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','completed','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_diplomacy_engagement_time ON diplomacy_demo.engagements(mission_id,held_at DESC);
CREATE INDEX IF NOT EXISTS ix_diplomacy_commitment_due ON diplomacy_demo.commitments(status,due_date) WHERE status NOT IN('completed','cancelled');
CREATE INDEX IF NOT EXISTS ix_diplomacy_events ON diplomacy_demo.commitment_events(commitment_id,happened_at DESC,event_id DESC);
COMMENT ON COLUMN diplomacy_demo.engagements.publication_state IS 'Publication workflow state, not a security classification or authorisation substitute.';